WITH flagged AS (SELECT *, CASE WHEN started_at - LAG(started_at) OVER (PARTITION BY customer_id ORDER BY started_at, id) > INTERVAL '14' DAY THEN 1 ELSE 0 END AS session_start_flag FROM sessions), sessionized AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY customer_id ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM flagged) SELECT s.id, s.customer_id, s.browser, s.country, s.session_start_flag, s.session_no, (SELECT AVG(t2.amount) FROM orders t2 WHERE t2.customer_id = s.customer_id) AS avg_order_amount FROM sessionized s ORDER BY avg_order_amount NULLS LAST;
